<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class IconsSeeder extends Seeder
{
    /**
     * Har icon ka class_name, icon_name, display_name aur category store hoga.
     */
    public function run(): void
    {
        DB::table('icons')->truncate();

        $icons = $this->getIcons();

        // Batch insert for performance
        $chunks = array_chunk($icons, 100);
        foreach ($chunks as $chunk) {
            DB::table('icons')->insert($chunk);
        }

        $this->command->info('Total icons seeded: ' . count($icons));
    }

